    /**
     * @method
     * @name polymarket#watchPositions
     * @description watches information on the open positions of the account, the venue pushes a full portfolio snapshot roughly every five seconds
     * @see https://docs.polymarket.com/perps/realtime-updates
     * @param {string[]} [symbols] list of unified market symbols
     * @param {int} [since] not used by polymarket watchPositions
     * @param {int} [limit] not used by polymarket watchPositions
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list of [position structures]{@link https://docs.ccxt.com/#/?id=position-structure}
     */
    public CompletableFuture<List<Position>> watchPositions(List<String> symbols, Long since, Long limit, Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            (this.loadMarkets(false, new HashMap<String, Object>() {{}})).join();
            (this.authenticate(new HashMap<String, Object>() {{}})).join();
            List<String> symbolsNormalized = this.marketSymbols(symbols, (Object) null, true, false, false);
            String url = this.safeString(this.urls.get("api"), "ws");
            Client client = this.client(url);
            this.setPositionsCache(client, symbolsNormalized);
            Object fetchPositionsSnapshot = this.handleOption("watchPositions", "fetchPositionsSnapshot", true);
            Object awaitPositionsSnapshot = this.handleOption("watchPositions", "awaitPositionsSnapshot", true);
            if ((java.util.Objects.equals(fetchPositionsSnapshot, true)) && (java.util.Objects.equals(awaitPositionsSnapshot, true)) && (java.util.Objects.equals(this.positions, null)))
            {
                // the portfolio channel pushes one snapshot at subscribe time and
                // then only on changes, so the first call hydrates over rest
                Object snapshot = client.future("fetchPositionsSnapshot").getFuture().join();
                return this.filterBySymbolsSinceLimit(snapshot, symbolsNormalized, since, limit, true);
            }
            List<String> subscribeHashes = new ArrayList<String>(Arrays.asList("portfolio"));
            Map<String, Object> request = (Map<String, Object>) this.sendSubscription("sub", new ArrayList<Object>(Arrays.asList("portfolio")), new ArrayList<Object>(Arrays.asList("positions")), subscribeHashes, new HashMap<String, Object>() {{}}, parameters, subscribeHashes);
            List<Object> newPositions = (List<Object>) (this.watch(url, "positions", request, "portfolio", null)).join();
            if (this.newUpdates)
            {
                return this.filterBySymbolsSinceLimit(newPositions, symbolsNormalized, since, limit, true);
            }
            return this.filterBySymbolsSinceLimit(this.positions, symbolsNormalized, since, limit, true);
        }).thenApply(res -> ((List<?>) res).stream().map(Position::new).collect(Collectors.toList()));

    }

    public void setPositionsCache(Client client, List<String> symbols)
    {
        if (!java.util.Objects.equals(this.positions, null))
        {
            return;
        }
        Object fetchPositionsSnapshot = this.handleOption("watchPositions", "fetchPositionsSnapshot", true);
        if (java.util.Objects.equals(fetchPositionsSnapshot, true))
        {
            String messageHash = "fetchPositionsSnapshot";
            if (!(client.futures.containsKey(messageHash)))
            {
                client.future(messageHash);
                this.spawn(() -> { try { this.loadPositionsSnapshot(client, messageHash); } catch(Exception _e) { throw new RuntimeException(_e); } });
            }
        } else
        {
            this.positions = new ArrayCache.ArrayCacheBySymbolBySide();
        }
    }

    public CompletableFuture<Object> loadPositionsSnapshot(Client client, String messageHash)
    {

        return BaseExchange.supplyAsync(() -> {

            List<Position> positions = (this.fetchPositions((List<String>) null, new HashMap<String, Object>() {{}})).join();
            this.positions = new ArrayCache.ArrayCacheBySymbolBySide();
            Object cache = this.positions;
            for (var i = 0; i < ((List<?>)positions).size(); i++)
            {
                ((io.github.ccxt.ws.ArrayCache) cache).append((positions == null || i < 0 || i >= positions.size() ? null : positions.get(i)));
            }
            // don't remove the future from the .futures cache
            if (client.futures.containsKey(messageHash))
            {
                io.github.ccxt.ws.Future future = (client.futures == null || messageHash == null ? null : client.futures.get(messageHash));
                future.resolve(cache);
            }
            client.resolve(cache, "positions");
            return null;
        });

    }

    /**
     * @method
     * @name polymarket#watchBalance
     * @description watches the account margin summary, the venue pushes a full portfolio snapshot roughly every five seconds
     * @see https://docs.polymarket.com/perps/realtime-updates
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [balance structure]{@link https://docs.ccxt.com/#/?id=balance-structure}
     */
    public CompletableFuture<Balances> watchBalance(Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            (this.loadMarkets(false, new HashMap<String, Object>() {{}})).join();
            (this.authenticate(new HashMap<String, Object>() {{}})).join();
            String url = this.safeString(this.urls.get("api"), "ws");
            Client client = this.client(url);
            this.setBalanceCache(client);
            Object fetchBalanceSnapshot = this.handleOption("watchBalance", "fetchBalanceSnapshot", true);
            Object awaitBalanceSnapshot = this.handleOption("watchBalance", "awaitBalanceSnapshot", true);
            Boolean balanceLoaded = (((Map<?, ?>)this.balance).containsKey("info"));
            if ((java.util.Objects.equals(fetchBalanceSnapshot, true)) && (java.util.Objects.equals(awaitBalanceSnapshot, true)) && (!Boolean.TRUE.equals(balanceLoaded)))
            {
                // the portfolio channel pushes one snapshot at subscribe time and
                // then only on changes, so the first call hydrates over rest
                Object snapshot = client.future("fetchBalanceSnapshot").getFuture().join();
                return snapshot;
            }
            List<String> subscribeHashes = new ArrayList<String>(Arrays.asList("portfolio"));
            Map<String, Object> request = (Map<String, Object>) this.sendSubscription("sub", new ArrayList<Object>(Arrays.asList("portfolio")), new ArrayList<Object>(Arrays.asList("balance")), subscribeHashes, new HashMap<String, Object>() {{}}, parameters, subscribeHashes);
            return (this.watch(url, "balance", request, "portfolio", null)).join();
        }).thenApply(Balances::new);

    }

    public void setBalanceCache(Client client)
    {
        Boolean balanceLoaded = (((Map<?, ?>)this.balance).containsKey("info"));
        if (Boolean.TRUE.equals(balanceLoaded))
        {
            return;
        }
        Object fetchBalanceSnapshot = this.handleOption("watchBalance", "fetchBalanceSnapshot", true);
        if (java.util.Objects.equals(fetchBalanceSnapshot, true))
        {
            String messageHash = "fetchBalanceSnapshot";
            if (!(client.futures.containsKey(messageHash)))
            {
                client.future(messageHash);
                this.spawn(() -> { try { this.loadBalanceSnapshot(client, messageHash); } catch(Exception _e) { throw new RuntimeException(_e); } });
            }
        }
    }

    public CompletableFuture<Object> loadBalanceSnapshot(Client client, String messageHash)
    {

        return BaseExchange.supplyAsync(() -> {

            Balances balance = (this.fetchBalance(new HashMap<String, Object>() {{}})).join();
            this.balance = this.extend(this.balance, balance);
            // don't remove the future from the .futures cache
            if (client.futures.containsKey(messageHash))
            {
                io.github.ccxt.ws.Future future = (client.futures == null || messageHash == null ? null : client.futures.get(messageHash));
                future.resolve(this.balance);
            }
            client.resolve(this.balance, "balance");
            return null;
        });

    }

    public void handlePortfolio(Client client, Map<String, Object> message)
    {
        //
        //     {
        //         "ch": "portfolio",
        //         "ts": 1788546565789,
        //         "sq": 35879860000,
        //         "data": {
        //             "positions": [
        //                 {
        //                     "instrument_id": 6,
        //                     "symbol": "BTC-USD",
        //                     "size": "0.001",
        //                     "entry_price": "79650.0",
        //                     "leverage": 10,
        //                     "cross": true,
        //                     "initial_margin": "7.97",
        //                     "maintenance_margin": "3.99",
        //                     "position_value": "79.65",
        //                     "liquidation_price": "72000.0",
        //                     "unrealized_pnl": "-0.10",
        //                     "return_on_equity": "-0.0125",
        //                     "cumulative_funding": "0.01",
        //                     "adl_index": 0
        //                 }
        //             ],
        //             "margin": {
        //                 "total_account_value": "100.00",
        //                 "available_order_margin": "90.00",
        //                 "total_initial_margin": "10.00",
        //                 "total_maintenance_margin": "5.00",
        //                 "total_position_value": "50.00"
        //             },
        //             "withdrawable": "90.00",
        //             "in_liquidation": false,
        //             "timestamp": 1788546565789
        //         }
        //     }
        //
        Map<String, Object> data = (Map<String, Object>) this.safeDict(message, "data", new HashMap<String, Object>() {{}});
        Long timestamp = this.safeInteger(data, "timestamp");
        if (java.util.Objects.equals(this.positions, null))
        {
            this.positions = new ArrayCache.ArrayCacheBySymbolBySide();
        }
        Object cache = this.positions;
        List<Object> rows = (List<Object>) this.safeList(data, "positions", new ArrayList<Object>(Arrays.asList()));
        List<Object> newPositions = new ArrayList<Object>(Arrays.asList());
        for (var i = 0; i < ((List<?>)rows).size(); i++)
        {
            Map<String, Object> row = (Map<String, Object>) this.safeDict(rows, i, new HashMap<String, Object>() {{}});
            Map<String, Object> extended = this.extend(row, new HashMap<String, Object>() {{
                put( "timestamp", timestamp );
            }});
            Map<String, Object> position = (Map<String, Object>) this.parsePosition((Map<String, Object>) (extended), (Map<String, Object>) null);
            ((List<Object>)newPositions).add(position);
            ((io.github.ccxt.ws.ArrayCache) cache).append(position);
        }
        client.resolve(newPositions, "positions");
        Map<String, Object> margin = (Map<String, Object>) this.safeDict(data, "margin", new HashMap<String, Object>() {{}});
        Map<String, Object> result = new HashMap<String, Object>() {{
            put( "info", data );
            put( "timestamp", timestamp );
            put( "datetime", Polymarket.this.iso8601(timestamp) );
        }};
        Map<String, Object> account = this.account();
        account.put("total", this.safeString(margin, "total_account_value"));
        account.put("free", this.safeString(margin, "available_order_margin"));
        account.put("used", this.safeString(margin, "total_initial_margin"));
        // pUSD is the only collateral asset on the venue
        result.put("PUSD", account);
        this.balance = this.safeBalance(result);
        client.resolve(this.balance, "balance");
    }

    public void handleAck(Client client, Object message)
    {
        //
        // subscribe or unsubscribe acknowledgement
        //
        //     { "id": 1, "data": [ { "status": "ok" } ] }
        //     { "id": 2, "data": [ { "status": "err", "error": "invalid channel" } ] }
        //
        // ping reply
        //
        //     { "id": 99, "ts": 1788546831854, "data": { "status": "ok", "ts": 1788546831854, "sq": 35879934302 } }
        //
        String id = this.safeString(message, "id");
        Object data = this.safeValue(message, "data");
        if (!(data instanceof List))
        {
            // post replies carry a data object - the auth op is matched back
            // through its pending entry, anything else counts like a pong
            if (!java.util.Objects.equals(id, null))
            {
                String postKey = ("req:" + id);
                Map<String, Object> postPending = (Map<String, Object>) this.safeDict(client.subscriptions, postKey, (Object) null);
                if (!java.util.Objects.equals(postPending, null))
                {
                    client.subscriptions.remove(postKey);
                    String postAction = this.safeString(postPending, "method");
                    if (java.util.Objects.equals(postAction, "auth"))
                    {
                        String authStatus = this.safeString(data, "status");
                        if (java.util.Objects.equals(authStatus, "ok"))
                        {
                            // resolve the future object directly so it stays
                            // cached and later authenticate calls reuse it
                            io.github.ccxt.ws.Future future = client.futures.get("authenticated");
                            if (!java.util.Objects.equals(future, null))
                            {
                                future.resolve(true);
                            }
                        } else
                        {
                            var authError = new AuthenticationError(((this.id + " authentication failed ") + this.json(data)));
                            client.reject(authError, "authenticated");
                            if (client.subscriptions.containsKey("authenticated"))
                            {
                                client.subscriptions.remove("authenticated");
                            }
                        }
                        return;
                    }
                }
            }
            client.lastPong = ((Number)this.safeInteger(message, "ts", this.milliseconds())).longValue();
            return;
        }
        if (java.util.Objects.equals(id, null))
        {
            return;
        }
        String key = ("req:" + id);
        Map<String, Object> pending = (Map<String, Object>) this.safeDict(client.subscriptions, key, (Object) null);
        if (java.util.Objects.equals(pending, null))
        {
            return;
        }
        client.subscriptions.remove(key);
        List<Object> messageHashes = (List<Object>) this.safeList(pending, "messageHashes", new ArrayList<Object>(Arrays.asList()));
        List<Object> subMessageHashes = (List<Object>) this.safeList(pending, "subMessageHashes", new ArrayList<Object>(Arrays.asList()));
        String action = this.safeString(pending, "method");
        String errorMessage = null;
        for (var i = 0; i < ((List<?>)data).size(); i++)
        {
            Map<String, Object> entry = (Map<String, Object>) this.safeDict(data, i, new HashMap<String, Object>() {{}});
            String status = this.safeString(entry, "status");
            if (java.util.Objects.equals(status, "err"))
            {
                errorMessage = this.safeString(entry, "error");
            }
        }
        if (!java.util.Objects.equals(errorMessage, null))
        {
            var error = new ExchangeError(((this.id + " ") + errorMessage));
            for (var i = 0; i < ((List<?>)messageHashes).size(); i++)
            {
                client.reject(error, (messageHashes == null || i < 0 || i >= messageHashes.size() ? null : messageHashes.get(i)));
                // clearing the awaited hash lets a later call resend, and a
                // failed subscribe must also clear the shared hash the base
                // watch registered - a failed unsubscribe keeps the live
                // subscription untouched instead
                Object messageHash = (messageHashes == null || i < 0 || i >= messageHashes.size() ? null : messageHashes.get(i));
                if ((messageHash != null && client.subscriptions.containsKey(messageHash)))
                {
                    client.subscriptions.remove((String)messageHash);
                }
                if (java.util.Objects.equals(action, "sub"))
                {
                    Object subMessageHash = (subMessageHashes == null || i < 0 || i >= subMessageHashes.size() ? null : subMessageHashes.get(i));
                    if ((subMessageHash != null && client.subscriptions.containsKey(subMessageHash)))
                    {
                        client.subscriptions.remove((String)subMessageHash);
                    }
                }
            }
            return;
        }
        if (java.util.Objects.equals(action, "unsub"))
        {
            String topic = this.safeString(pending, "topic");
            String symbol = this.safeString(pending, "symbol");
            if (!java.util.Objects.equals(symbol, null))
            {
                if (java.util.Objects.equals(topic, "orderbook"))
                {
                    if (((Map<?, ?>)this.orderbooks).containsKey(symbol))
                    {
                        ((Map<String,Object>)this.orderbooks).remove((String)symbol);
                    }
                } else if (java.util.Objects.equals(topic, "trades"))
                {
                    if (((Map<?, ?>)this.trades).containsKey(symbol))
                    {
                        ((Map<String,Object>)this.trades).remove((String)symbol);
                    }
                } else if (java.util.Objects.equals(topic, "ticker"))
                {
                    if (((Map<?, ?>)this.tickers).containsKey(symbol))
                    {
                        ((Map<String,Object>)this.tickers).remove((String)symbol);
                    }
                } else if (java.util.Objects.equals(topic, "ohlcv"))
                {
                    String timeframe = this.safeString(pending, "timeframe");
                    if ((!java.util.Objects.equals(timeframe, null)) && (((Map<?, ?>)this.ohlcvs).containsKey(symbol)))
                    {
                        if (((Map<?, ?>)((Map<?, ?>)this.ohlcvs).get(symbol)).containsKey(timeframe))
                        {
                            ((Map<String,Object>)((Map<?, ?>)this.ohlcvs).get(symbol)).remove((String)timeframe);
                        }
                    }
                }
            }
            for (var i = 0; i < ((List<?>)messageHashes).size(); i++)
            {
                this.cleanUnsubscription(client, (String) ((subMessageHashes == null || i < 0 || i >= subMessageHashes.size() ? null : subMessageHashes.get(i))), (String) ((messageHashes == null || i < 0 || i >= messageHashes.size() ? null : messageHashes.get(i))), false);
            }
        }
    }

    public void handleMessage(Client client, Object message)
    {
        String ch = this.safeString(message, "ch");
        if (java.util.Objects.equals(ch, null))
        {
            this.handleAck(client, message);
            return;
        }
        List<Object> parts = new ArrayList<Object>(Arrays.asList(((String)ch).split(java.util.regex.Pattern.quote("::"))));
        String family = this.safeString(parts, 0, "");
        Map<String, Object> methods = new HashMap<String, Object>() {{
            put( "book", "handleOrderBook");
            put( "bbo", "handleBidAsk");
            put( "trades", "handleTrades");
            put( "tickers", "handleTicker");
            put( "klines", "handleOHLCV");
            put( "orders", "handleOrder");
            put( "fills", "handleMyTrades");
            put( "portfolio", "handlePortfolio");
        }};
        Object method = this.safeValue(methods, family);
        if (!java.util.Objects.equals(method, null))
        {
            Helpers.callDynamically(this, method, new Object[] {client, message});
        }
    }

    public Object ping(Client client)
    {
        return new HashMap<String, Object>() {{
            put( "id", Polymarket.this.requestId() );
            put( "req", "post" );
            put( "op", new HashMap<String, Object>() {{
                put( "type", "ping" );
            }} );
        }};
    }
